content = FRONTEND.encode("utf-8")
digest = sha256(content).hexdigest()[:20]
folder = Path(gettempdir()) / ("cm_manager_" + digest)
folder.mkdir(mode=0o700, exist_ok=True)
target = folder / "index.html"
if not target.exists():
    with NamedTemporaryFile(dir=folder, delete=False) as temporary:
        temporary.write(content)
    Path(temporary.name).replace(target)

board = components.declare_component("chokomana_manager_" + digest, path=str(folder))
board(key="chokomana_manager", default=None)
